75	/**
76	 * Generate PKCE parameters for OAuth flow.
77	 *
78	 * @returns PKCE parameters including code verifier, challenge, and state
79	 */
80	export function generatePKCEParams(): PKCEParams {
81	  // Generate code verifier (43-128 characters)
82	  // using 64 bytes results in ~86 characters, safely above the minimum of 43
83	  const codeVerifier = crypto.randomBytes(64).toString('base64url');
84	
85	  // Generate code challenge using SHA256
86	  const codeChallenge = crypto
87	    .createHash('sha256')
88	    .update(codeVerifier)
89	    .digest('base64url');
90	
91	  // Generate state for CSRF protection
92	  const state = crypto.randomBytes(16).toString('base64url');
93	
94	  return { codeVerifier, codeChallenge, state };
95	}
