120	    (resolve, reject) => {
121	      let serverPort: number;
122	
123	      const server = http.createServer(
124	        async (req: http.IncomingMessage, res: http.ServerResponse) => {
125	          try {
126	            const url = new URL(req.url!, `http://localhost:${serverPort}`);
127	
128	            if (url.pathname !== REDIRECT_PATH) {
129	              res.writeHead(404);
130	              res.end('Not found');
131	              return;
132	            }
133	
134	            const code = url.searchParams.get('code');
135	            const state = url.searchParams.get('state');
136	            const error = url.searchParams.get('error');
137	
138	            if (error) {
139	              res.writeHead(HTTP_OK, { 'Content-Type': 'text/html' });
140	              res.end(`
141	              <html>
142	                <body>
143	                  <h1>Authentication Failed</h1>
144	                  <p>Error: ${error.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</p>
145	                  <p>${(url.searchParams.get('error_description') || '').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</p>
146	                  <p>You can close this window.</p>
147	                </body>
148	              </html>
149	            `);
150	              server.close();
151	              reject(new Error(`OAuth error: ${error}`));
152	              return;
153	            }
154	
155	            if (!code || !state) {
156	              res.writeHead(400);
157	              res.end('Missing code or state parameter');
158	              return;
159	            }
160	
161	            if (state !== expectedState) {
162	              res.writeHead(400);
163	              res.end('Invalid state parameter');
164	              server.close();
165	              reject(new Error('State mismatch - possible CSRF attack'));
166	              return;
167	            }
168	
169	            // Send success response to browser
170	            res.writeHead(HTTP_OK, { 'Content-Type': 'text/html' });
171	            res.end(`
172	            <html>
173	              <body>
174	                <h1>Authentication Successful!</h1>
175	                <p>You can close this window and return to Gemini CLI.</p>
176	                <script>window.close();</script>
177	              </body>
178	            </html>
179	          `);
180	
181	            server.close();
182	            resolve({ code, state });
183	          } catch (error) {
184	            server.close();
185	            reject(error);
186	          }
187	        },
188	      );
189	
