197	
198	      const portStr = process.env['OAUTH_CALLBACK_PORT'];
199	      if (portStr) {
200	        const envPort = parseInt(portStr, 10);
201	        if (isNaN(envPort) || envPort <= 0 || envPort > 65535) {
202	          const error = new Error(
203	            `Invalid value for OAUTH_CALLBACK_PORT: "${portStr}"`,
204	          );
205	          portReject(error);
206	          reject(error);
207	          return;
208	        }
209	        listenPort = envPort;
210	      } else if (port !== undefined) {
211	        listenPort = port;
212	      }
213	
214	      server.listen(listenPort, () => {
215	        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
