225	      setTimeout(
226	        () => {
227	          server.close();
228	          reject(new Error('OAuth callback timeout'));
229	        },
230	        5 * 60 * 1000,
231	      );
232	    },
233	  );
234	
235	  return { port: portPromise, response: responsePromise };
236	}
